package com.aurevia.bff.outboundauth;
import static org.junit.jupiter.api.Assertions.assertEquals;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
import java.time.Duration;import java.util.concurrent.atomic.AtomicBoolean;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;import org.springframework.data.redis.core.ReactiveStringRedisTemplate;import org.springframework.data.redis.core.ReactiveValueOperations;import org.springframework.data.redis.core.script.RedisScript;import reactor.core.publisher.Flux;import reactor.core.publisher.Mono;import reactor.core.publisher.Sinks;
class LegacyTokenRefreshCoordinatorTest {
 @Test void concurrentRequestsCauseOneAcquisition(){ReactiveStringRedisTemplate redis=mock(ReactiveStringRedisTemplate.class);ReactiveValueOperations<String,String> values=mock(ReactiveValueOperations.class);when(redis.opsForValue()).thenReturn(values);AtomicBoolean lock=new AtomicBoolean();when(values.setIfAbsent(anyString(),anyString(),any(Duration.class))).thenAnswer(x->Mono.just(lock.compareAndSet(false,true)));when(redis.execute(org.mockito.ArgumentMatchers.<RedisScript<Long>>any(),anyList(),anyList())).thenReturn(Flux.just(1L));var ready=Sinks.<String>one();AtomicInteger calls=new AtomicInteger();var coordinator=new LegacyTokenRefreshCoordinator(redis);Mono<String> request=Mono.defer(()->coordinator.once("lock",()->Mono.delay(Duration.ofMillis(50)).map(i->{calls.incrementAndGet();ready.tryEmitValue("token");return "token";}),ready::asMono));Flux.range(0,30).flatMap(i->request).collectList().block(Duration.ofSeconds(5));assertEquals(1,calls.get());}
}
